import test from 'node:test';import {createRequire} from 'node:module';import path from 'node:path';import assert from 'node:assert/strict';
import {parseCompiledActions,classifyUnitRequest,parseFlightAck,ownUnitIdFromFlight,validatePrivateHandoff,materialWireArgs,ORIGIN} from './warehouse-units-stage-browser.mjs';
const refs={add:'a'.repeat(40),rename:'b'.repeat(40),delete:'c'.repeat(40),material:'d'.repeat(40)},scope={origin:ORIGIN,refs};
test('compiled export names map to unique real Next action identifiers',()=>{const js=Object.entries({addMaterialUnit:refs.add,renameMaterialUnit:refs.rename,deleteMaterialUnit:refs.delete,updateMaterial:refs.material}).map(([name,id])=>'createServerReference("'+id+'",callServer,void 0,findSourceMapURL,"'+name+'")').join(';');assert.deepEqual(parseCompiledActions([js]),refs);assert.throws(()=>parseCompiledActions([js+';createServerReference("'+'e'.repeat(40)+'",x,0,x,"addMaterialUnit")']));assert.throws(()=>parseCompiledActions(['no refs']));});
test('only exact current own action/args on approved warehouse routes are sent',()=>{const expected={kind:'unit-add',ref:refs.add,args:[{name:'QA own B'}]},request={url:ORIGIN+'/warehouse/items',method:'POST',headers:{'next-action':refs.add,'content-type':'text/plain;charset=UTF-8'},body:JSON.stringify(expected.args)};assert.equal(classifyUnitRequest(request,scope,expected).kind,'action');for(const patch of [{url:'https://prod.example/warehouse/items'},{url:ORIGIN+'/my'},{body:'[{"name":"other"}]'},{headers:{'next-action':refs.delete}},{method:'PUT'}])assert.equal(classifyUnitRequest({...request,...patch},scope,expected).kind,'deny');assert.equal(classifyUnitRequest(request,scope,null).kind,'deny');assert.equal(classifyUnitRequest({url:ORIGIN+'/_next/static/chunks/x.js',method:'GET',headers:{}},scope,null).kind,'read');assert.equal(classifyUnitRequest({url:ORIGIN+'/api/auth/signout',method:'GET',headers:{}},scope,null).kind,'deny');});
test('ACK parses exact Flight ok/used/role denials without exposing raw text',()=>{assert.deepEqual(parseFlightAck(200,'0:{"ok":true}',{expect:'ok'}),{status:'ok'});assert.deepEqual(parseFlightAck(200,'1:{"ok":false,"error":"Единица используется в номенклатуре. Сначала выберите другую единицу"}',{expect:'used-denied'}),{status:'used-denied'});assert.deepEqual(parseFlightAck(500,'0:E{"digest":"8373"}',{expect:'role-denied'}),{status:'role-denied'});for(const [status,body,expect]of [[400,'bad csrf','role-denied'],[303,'login','role-denied'],[200,'0:{"ok":false,"error":"duplicate"}','used-denied'],[500,'0:E{"digest":"8373"}','ok'],[200,'0:{"ok":true}','role-denied']])assert.throws(()=>parseFlightAck(status,body,{expect}));});
test('new unit CUID is learned only from exact own tag in bounded Flight rows',()=>{const body='0:["$",null,{"rows":[{"id":"existing","name":"real"},{"id":"ownb1","name":"QA own B"}]}]';assert.equal(ownUnitIdFromFlight(body,'QA own B'),'ownb1');assert.throws(()=>ownUnitIdFromFlight(body,'missing'));assert.throws(()=>ownUnitIdFromFlight(body+'\n1:{"id":"ownb2","name":"QA own B"}','QA own B'));});
test('private handoff requires four exact own actor roles and secure origin cookies',()=>{const pre={runId:'80502171-fcf9-4189-a3f8-c8a77e94efad',revision:'a'.repeat(40),signature:'b'.repeat(64),actors:Object.fromEntries(['ADMIN','MANAGER','ENGINEER','DIRECTOR'].map(r=>[r,{id:'own'+r,roles:[r]}]))},profiles=Object.fromEntries(Object.entries(pre.actors).map(([role,actor])=>[role,{...actor,cookies:[{name:'authjs.session-token',value:'private',url:ORIGIN,httpOnly:true,secure:true,sameSite:'Lax'}]}])),input={authorized:true,origin:ORIGIN,revision:pre.revision,identity:{hostname:'crm-staging',revision:pre.revision},pre,profiles};assert.doesNotThrow(()=>validatePrivateHandoff(input));assert.throws(()=>validatePrivateHandoff({...input,profiles:{...profiles,ADMIN:{...profiles.ADMIN,roles:['DIRECTOR']}}}));assert.throws(()=>validatePrivateHandoff({...input,origin:'https://prod.example'}));assert.throws(()=>validatePrivateHandoff({...input,profiles:{...profiles,ENGINEER:{...profiles.ENGINEER,cookies:[{...profiles.ENGINEER.cookies[0],url:'https://prod.example'}]}}}));});

test('prefetch is aborted without opening unrelated screens or failing the run',()=>{assert.equal(classifyUnitRequest({url:ORIGIN+'/projects',method:'GET',headers:{'next-router-prefetch':'1'}},scope,null).kind,'abort-prefetch');assert.equal(classifyUnitRequest({url:ORIGIN+'/products',method:'GET',headers:{purpose:'prefetch'}},scope,null).kind,'abort-prefetch');assert.equal(classifyUnitRequest({url:ORIGIN+'/projects',method:'GET',headers:{}},scope,null).kind,'deny');});

test('actual installed Flight encoder preserves optional fields as $undefined',async()=>{const require=createRequire(import.meta.url),next=path.dirname(require.resolve('next/package.json'));const originalWebpack=globalThis.__webpack_require__,originalLoader=globalThis.__webpack_chunk_load__;try{globalThis.__webpack_require__=Object.assign(()=>{throw Error('NO_MODULE_LOAD');},{u:()=>''});globalThis.__webpack_chunk_load__=()=>{throw Error('NO_CHUNK_LOAD');};const flight=require(path.join(next,'dist/compiled/react-server-dom-webpack/client.browser.js'));const pre={ids:{materialActive:'own-active'},tags:{active:'QA own active'}},args=['own-active',{name:pre.tags.active,sku:undefined,unitId:'own-unit',categoryId:undefined,minStock:3,comment:undefined}],encoded=await flight.encodeReply(args);assert.deepEqual(JSON.parse(encoded),materialWireArgs(pre,'active','own-unit'));}finally{globalThis.__webpack_require__=originalWebpack;globalThis.__webpack_chunk_load__=originalLoader;}});
